package com.yeyamo_mobile.api.culture_service.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="language_user_progress") public class LanguageProgress{@Id private UUID id;@Column(name="user_id",nullable=false)private String userId;@Column(name="language_code",nullable=false)private String languageCode;@Column(name="lesson_id",nullable=false)private UUID lessonId;@Column(name="started_at",nullable=false)private Instant startedAt;@Column(name="completed_at")private Instant completedAt;private Integer score;@Column(name="attempt_count",nullable=false)private int attemptCount;@Version private long version;protected LanguageProgress(){}public static LanguageProgress start(String user,String language,UUID lesson){LanguageProgress p=new LanguageProgress();p.id=UUID.randomUUID();p.userId=user;p.languageCode=language;p.lessonId=lesson;p.startedAt=Instant.now();return p;}public void attempted(){attemptCount++;}public boolean complete(int value){if(completedAt!=null)return false;score=Math.max(0,Math.min(100,value));completedAt=Instant.now();return true;}public UUID getId(){return id;}public String getUserId(){return userId;}public String getLanguageCode(){return languageCode;}public UUID getLessonId(){return lessonId;}public Instant getStartedAt(){return startedAt;}public Instant getCompletedAt(){return completedAt;}public Integer getScore(){return score;}public int getAttemptCount(){return attemptCount;}}
